import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"与 Eramaker 的差异","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Difference.md","filePath":"translation/Difference.md"}`),a={name:`translation/Difference.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="与-eramaker-的差异" tabindex="-1">与 Eramaker 的差异 <a class="header-anchor" href="#与-eramaker-的差异" aria-label="Permalink to “与 Eramaker 的差异”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/diff" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/diff</a></p></blockquote><h2 id="修复的-bug-与不自然的行为" tabindex="-1">修复的 Bug 与不自然的行为 <a class="header-anchor" href="#修复的-bug-与不自然的行为" aria-label="Permalink to “修复的 Bug 与不自然的行为”">​</a></h2><h3 id="数组的最后一个元素无法使用" tabindex="-1">数组的最后一个元素无法使用 <a class="header-anchor" href="#数组的最后一个元素无法使用" aria-label="Permalink to “数组的最后一个元素无法使用”">​</a></h3><p>在 Eramaker 中，如果数组的最后一个元素不为 0，读取存档时数据会被<strong>破坏</strong>。</p><p>Emuera 不存在这个问题。</p><p>这个问题源于 Eramaker 没有统一保存与读取的规范，而 Emuera 以保存时的规范为准。 因此，用 Eramaker 保存、用 Emuera 读取不会重现该问题；但用 Emuera 保存、用 Eramaker 读取时，问题会重现。</p><h3 id="单目运算符-的异常" tabindex="-1">单目运算符 <code>-</code> 的异常 <a class="header-anchor" href="#单目运算符-的异常" aria-label="Permalink to “单目运算符 - 的异常”">​</a></h3><p>在 Eramaker 中，存在诸如 <code>-100 &lt; 0</code> 结果为<code>假</code>等问题。</p><p>Emuera 不存在这个问题。</p><h3 id="文件的最后一行不会被读取" tabindex="-1">文件的最后一行不会被读取 <a class="header-anchor" href="#文件的最后一行不会被读取" aria-label="Permalink to “文件的最后一行不会被读取”">​</a></h3><p>Eramaker 会忽略没有换行符的行。</p><p>也就是说，无论 <code>CSV</code> 还是 <code>ERB</code> 文件，其最后一行都会被忽略。</p><p>Emuera 不会重现该行为。</p><h3 id="数组中存在多余的元素时会被忽略" tabindex="-1">数组中存在多余的元素时会被忽略 <a class="header-anchor" href="#数组中存在多余的元素时会被忽略" aria-label="Permalink to “数组中存在多余的元素时会被忽略”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 34</span></span></code></pre></div><p>在 Eramaker 中，上述表达式会把 <code>34</code> 赋值给 <code>A:1</code>。</p><p>而在 Emuera 中，这会报错。</p><h3 id="无法以特定格式调用数组" tabindex="-1">无法以特定格式调用数组 <a class="header-anchor" href="#无法以特定格式调用数组" aria-label="Permalink to “无法以特定格式调用数组”">​</a></h3><p>在 Eramaker 中，可以使用 <code>A:0</code>、<code>A:(COUNT+1)</code> 这样的变量写法。</p><p>但在二重数组变量中写成 <code>ABL:0:2</code> 或 <code>TALENT:(COUNT+1):2</code> 时就会出错。</p><p>此外，调用字符串变量时若省略参数，也可能出错。</p><p>Emuera 不存在这个问题。</p><p>二重数组的参数无论是常量还是表达式都不会出错，字符串变量的参数也可以省略。</p><h3 id="csv-中的异常数字被当作整数处理" tabindex="-1">CSV 中的异常数字被当作整数处理 <a class="header-anchor" href="#csv-中的异常数字被当作整数处理" aria-label="Permalink to “CSV 中的异常数字被当作整数处理”">​</a></h3><div class="language-csv"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">csv</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">0,ローター,200</span></span>
<span class="line"><span style="color:#E6E6E6;">0xFF,ルーター,200</span></span></code></pre></div><p>如果在 <code>Item.csv</code> 中出现上述内容，Eramaker 会把 <code>0xFF</code> 解释为 0，于是 <code>TALENT:0</code> 被定义为<code>路由器</code>。</p><p>Emuera 不会重现该行为，而是报错并使该定义无效，<code>TALENT:0</code> 被定义为<code>转子</code>。</p><h3 id="不自然的写法也能工作" tabindex="-1">不自然的写法也能工作 <a class="header-anchor" href="#不自然的写法也能工作" aria-label="Permalink to “不自然的写法也能工作”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">99999</span><span style="color:#D4D4D4;"> +-</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">=</span><span style="color:#E6E6E6;">@</span><span style="color:#D4D4D4;">=+</span><span style="color:#B5CEA8;">123</span><span style="color:#D4D4D4;">|*?=</span><span style="color:#9CDCFE;">Y</span></span></code></pre></div><p>上述表达式在 Eramaker 中可以工作。</p><p>在 Emuera 中则会报错。</p><h2 id="与-eramaker-的其他差异" tabindex="-1">与 Eramaker 的其他差异 <a class="header-anchor" href="#与-eramaker-的其他差异" aria-label="Permalink to “与 Eramaker 的其他差异”">​</a></h2><h3 id="sif-的下一行是空行、注释行等的情况" tabindex="-1"><code>SIF</code> 的下一行是空行、注释行等的情况 <a class="header-anchor" href="#sif-的下一行是空行、注释行等的情况" aria-label="Permalink to “SIF 的下一行是空行、注释行等的情况”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">SIF</span><span style="color:#9CDCFE;"> 条件式</span></span>
<span class="line"><span style="color:#6A9955;">  ;注释</span></span>
<span class="line"><span style="color:#569CD6;">  PRINT</span><span style="color:#9CDCFE;"> hogehoge</span></span></code></pre></div><p>对于上述脚本，Eramaker 总是会执行 <code>PRINT</code> 行，因为它不认为 <code>SIF</code> 的下一行是 <code>;注释</code>。</p><p>Emuera 与吉里吉里（Kirikiri）等一样，只有在条件式为真时才执行 <code>PRINT</code> 行。</p><p>Emuera 会把空行和注释行视为完全不存在，因此把 <code>SIF</code> 的下一行识别为 <code>PRINT hogehoge</code>。</p><p>另外，Eramaker 允许在 <code>SIF</code> 的下一行放置 <code>IF</code> 或 <code>REPEAT</code> 语句，但这在许多情况下并非作者的意图，因此 Emuera 限制了可以紧跟在 <code>SIF</code> 后面的行。</p><h3 id="省略-if、elseif-等参数时的行为" tabindex="-1">省略 <code>IF</code>、<code>ELSEIF</code> 等参数时的行为 <a class="header-anchor" href="#省略-if、elseif-等参数时的行为" aria-label="Permalink to “省略 IF、ELSEIF 等参数时的行为”">​</a></h3><p>在 Eramaker 中，如果省略 <code>IF</code>、<code>ELSEIF</code> 或赋值语句的参数，行为是未定义的。</p><p>不过，如果省略 <code>RETURN</code> 的参数，则相当于 <code>RETURN 0</code>。</p><p>Emuera 总是把省略的参数解释为 0，因此 <code>IF</code> 以下的语句永远不会执行，但会给出警告。</p><h3 id="函数名允许使用的字符" tabindex="-1">函数名允许使用的字符 <a class="header-anchor" href="#函数名允许使用的字符" aria-label="Permalink to “函数名允许使用的字符”">​</a></h3><p>在 Eramaker 中，包括符号和双字节字符在内的所有字符都可以使用。</p><p>Emuera 也允许双字节字符，但不允许除 <code>_</code>（下划线）以外的符号。</p><p>此外，Emuera 不建议以半角数字作为函数名的开头。</p><p>下面的脚本在 Eramaker 中可以工作，但在 Emuera 中会报错。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">CALL</span><span style="color:#E6E6E6;"> \\.,)(][</span><span style="color:#D4D4D4;">+-%*</span><span style="color:#E6E6E6;"> 　@</span><span style="color:#D4D4D4;">&amp;</span><span style="color:#E6E6E6;">$</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6E6E6;">@\\.,)(][</span><span style="color:#D4D4D4;">+-%*</span><span style="color:#E6E6E6;"> 　@</span><span style="color:#D4D4D4;">&amp;</span><span style="color:#E6E6E6;">$</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 函数</span><span style="color:#E6E6E6;">@\\.,)(][</span><span style="color:#D4D4D4;">+-%*</span><span style="color:#E6E6E6;"> 　@</span><span style="color:#D4D4D4;">&amp;</span><span style="color:#E6E6E6;">$被调用了。</span></span>
<span class="line"><span style="color:#C586C0;">  RETURN</span><span style="color:#B5CEA8;"> 0</span></span></code></pre></div><p>在 Emuera 中，如果函数名包含 <code>,</code> 或 <code>(</code>，会被误认为是函数参数。</p><p>另外，如果函数名中包含 <code>@</code> 或运算符符号，<code>LOCAL@函数名</code> 这样的调用将无法正常工作。</p><p>如果函数名包含 <code>{}</code> 或 <code>%</code>，<code>CALLFORM</code> 调用会受到影响。</p><p>因此，Emuera 与 <code>C#</code>、吉里吉里（Kirikiri）等许多编程语言一样，禁止在函数名中使用符号。</p><p>从 ver 1.721 起，这是一个<code>警告 Lv 1</code>，而不会立即作为错误终止，但它仍可能在某处引发非预期的行为。</p><p>另外，如果函数名以半角数字开头，就无法作为<code>表达式中可用的函数</code>来调用。</p><p>这是因为表达式会查看单个字符，来判断它是数字、变量还是函数。</p><h3 id="rand-的行为" tabindex="-1"><code>RAND</code> 的行为 <a class="header-anchor" href="#rand-的行为" aria-label="Permalink to “RAND 的行为”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> RAND</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">X</span></span></code></pre></div><p>对于上面的表达式，当 <code>X</code> 为 0 时，Eramaker 返回 0。</p><p>否则，它返回（0 到 32767 之间的随机数）%（<code>X</code> 的绝对值）。</p><p>这种方式在 <code>X</code> 为负数时也能工作，永远不会返回大于 32767 的值，而且在 <code>X</code> 大于 1000 时偏差不可忽视。</p><p>Emuera 没有重现这些特征。</p><p>Emuera 返回（0 到 18446744073709551615 之间的随机数）%（<code>X</code>）。</p><p>当 <code>X</code> 为 0 或负数时，Emuera 会报错。</p><p>（这是为了统一返回值，依据官方说明「<code>RAND:A</code> 的返回值是 0 到 A-1 之间的整数」。）</p><p>另外，<code>X</code> 的有效范围是 1 到 9223372036854775807（64 位有符号整数的正数范围）。</p><p>如果 <code>X</code> 在 100 万亿左右以下，则偏差小到无法察觉。</p><h3 id="wait-的行为" tabindex="-1"><code>WAIT</code> 的行为 <a class="header-anchor" href="#wait-的行为" aria-label="Permalink to “WAIT 的行为”">​</a></h3><p>在 Eramaker 中，执行 <code>WAIT</code> 指令时不会换行，而是在按下 <code>Enter</code> 键时换行。</p><p>在 Emuera 中，如果执行 <code>WAIT</code> 指令时光标位于一行中间，则会换行；而在<code>按下 Enter 键</code>、<code>左键点击</code>时不会换行。</p><h3 id="jump-的行为" tabindex="-1"><code>JUMP</code> 的行为 <a class="header-anchor" href="#jump-的行为" aria-label="Permalink to “JUMP 的行为”">​</a></h3><p>在 Eramaker 中，无法从通过 <code>CALL</code> 调用的函数中 <code>JUMP</code> 出去。</p><p>在 Emuera 中，即使是通过 <code>CALL</code> 调用的函数也可以 <code>JUMP</code>。</p><p>在 <code>JUMP</code> 的目标中 <code>RETURN</code>，与在 <code>JUMP</code> 的来源函数中 <code>RETURN</code> 的行为相同。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">FOO</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 函数</span><span style="color:#E6E6E6;">@</span><span style="color:#9CDCFE;">FOO</span></span>
<span class="line"><span style="color:#C586C0;">  JUMP</span><span style="color:#DCDCAA;"> BAR</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">BAR</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 函数</span><span style="color:#E6E6E6;">@</span><span style="color:#9CDCFE;">BAR</span></span>
<span class="line"><span style="color:#C586C0;">  RETURN</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">FOOBAR</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 函数</span><span style="color:#E6E6E6;">@</span><span style="color:#9CDCFE;">FOOBAR</span></span>
<span class="line"><span style="color:#C586C0;">  CALL</span><span style="color:#DCDCAA;"> FOO</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTW</span><span style="color:#9CDCFE;"> 回到了函数</span><span style="color:#E6E6E6;">@</span><span style="color:#9CDCFE;">FOOBAR</span></span></code></pre></div><p>Eramaker 输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>试图用 JUMP 调用一个通过 CALL 调用的函数。</span></span></code></pre></div><p>Emuera 输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>函数@FOOBAR</span></span>
<span class="line"><span>函数@FOO</span></span>
<span class="line"><span>函数@BAR</span></span>
<span class="line"><span>回到了函数@FOOBAR</span></span></code></pre></div><h3 id="callname-的行为" tabindex="-1"><code>CALLNAME</code> 的行为 <a class="header-anchor" href="#callname-的行为" aria-label="Permalink to “CALLNAME 的行为”">​</a></h3><p>在 Eramaker 中，引用 <code>CALLNAME</code> 时，如果 <code>CALLNAME</code> 是空字符串，会返回 <code>NAME</code> 的值来代替。</p><p>在 Emuera 中，如果 <code>CALLNAME</code> 是空字符串，则返回空字符串。</p><p>为了弥补这一差异，Emuera 提供了<code>当 CALLNAME 是空字符串时使用 NAME</code>的选项。</p><p>当该选项为 <code>YES</code> 时，如果在 <code>CharaXX.csv</code> 中未设置 <code>CALLNAME</code>，或将其设置为空字符串，就会被视为设置成了与 <code>NAME</code> 相同的字符串。</p><p>然而，即使使用该选项也无法完全重现。</p><p>例如，用 Eramaker 添加角色后用 Emuera 读取存档时，行为可能不同。</p><h3 id="printform-等-form-的展开" tabindex="-1"><code>PRINTFORM</code> 等 <code>FORM</code> 的展开 <a class="header-anchor" href="#printform-等-form-的展开" aria-label="Permalink to “PRINTFORM 等 FORM 的展开”">​</a></h3><p>Eramaker 会反复进行展开，直到没有可展开的内容为止。</p><p>如果存在自我引用或循环引用，就会冻结。</p><p>Emuera 只展开一次。</p><p>Eramaker 的展开可能如下所示：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>str = 想要展开的字符串</span></span>
<span class="line"><span>while(str 中存在 {～～})</span></span>
<span class="line"><span>  展开最左边的 {～～}</span></span>
<span class="line"><span>while(str 中存在 %～～%)</span></span>
<span class="line"><span>  展开最左边的 %～～%</span></span>
<span class="line"><span>while(str 中存在 ***)</span></span>
<span class="line"><span>  展开最左边的 ***</span></span>
<span class="line"><span>while(str 中存在 $$$)</span></span>
<span class="line"><span>  展开最左边的 $$$</span></span>
<span class="line"><span>while(str 中存在 +++)</span></span>
<span class="line"><span>  展开最左边的 +++</span></span>
<span class="line"><span>while(str 中存在 ///)</span></span>
<span class="line"><span>  展开最左边的 ///</span></span>
<span class="line"><span>while(str 中存在 ===)</span></span>
<span class="line"><span>  展开最左边的 ===</span></span></code></pre></div><p>由于这种行为，Eramaker 还允许如下写法：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> S1</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">2</span><span style="color:#569CD6;">%</span><span style="color:#B5CEA8;">3</span><span style="color:#569CD6;">%</span><span style="color:#B5CEA8;">4</span><span style="color:#569CD6;">%</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> S2</span><span style="color:#D4D4D4;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> S3</span><span style="color:#D4D4D4;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">4</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> S4</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORMSL</span><span style="color:#E6E6E6;"> STR:1</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#569CD6;"> %</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#569CD6;">%</span></span>
<span class="line"><span style="color:#569CD6;">DRAWLINE</span></span>
<span class="line"><span style="color:#6A9955;">;结果</span></span>
<span class="line"><span style="color:#6A9955;">;S1S2S3S4</span></span>
<span class="line"><span style="color:#6A9955;">;S1S2S3S4</span></span></code></pre></div><p>Emuera 不会重现这种情况。</p><h3 id="event-函数的属性" tabindex="-1">EVENT 函数的属性 <a class="header-anchor" href="#event-函数的属性" aria-label="Permalink to “EVENT 函数的属性”">​</a></h3><p>在 Eramaker 中，事件函数的调用方式如下：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>foreach(带有 #PRI 的函数)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  函数调用</span></span>
<span class="line"><span>  if(#SINGLE 且返回值为 1)</span></span>
<span class="line"><span>    break;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>foreach(没有 #PRI 也没有 #LATER 的函数)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  函数调用</span></span>
<span class="line"><span>  if(#SINGLE 且返回值为 1)</span></span>
<span class="line"><span>    break;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>foreach(带有 #LATER 的函数)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  函数调用</span></span>
<span class="line"><span>  if(#SINGLE 且返回值为 1)</span></span>
<span class="line"><span>    break;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>同时带有 <code>#PRI</code> 和 <code>#LATER</code> 的事件函数会被调用两次。</p><p><code>#SINGLE</code> 只在返回值为 1 时中断后续的函数调用。</p><p>另外，<code>#SINGLE</code> 对基于 <code>#PRI</code> 或 <code>#LATER</code> 的每一组函数调用分别生效。</p><p>ver 1.800（包含开发版则为 1.756alpha018）之后的 Emuera 完全重现了该行为。</p><p>在那之前的 Emuera 中，事件函数的调用方式如下。</p><p>根据 <code>#PRI</code>、<code>#LATER</code> 对函数列表排序：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>foreach(所有函数)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  函数调用</span></span>
<span class="line"><span>  if(#SINGLE 且返回值为 1)</span></span>
<span class="line"><span>    break;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果同时带有 <code>#PRI</code> 和 <code>#LATER</code>，则视为两者都没有。</p><p>如果函数调用被 <code>#SINGLE</code> 中断，则不论是否存在 <code>#PRI</code>、<code>#LATER</code>，该事件函数的调用都会结束。</p><p>另外，在 Emuera 1.751b 之前，<code>#SINGLE</code> 会在返回值不为 0 时中断后续的函数调用。</p><p>这在 1.752 中得到修复，当前版本与 Eramaker 一样，只在返回值为 1 时中断后续的函数调用。</p><h3 id="gamebase-csv-中「代码」的读取方法" tabindex="-1"><code>gamebase.csv</code> 中「代码」的读取方法 <a class="header-anchor" href="#gamebase-csv-中「代码」的读取方法" aria-label="Permalink to “gamebase.csv 中「代码」的读取方法”">​</a></h3><p>如果在 <code>gamebase.csv</code> 的代码中写入超出 Eramaker 可处理范围（<code>-2147483648</code> 到 <code>2147483647</code>）的数值，Eramaker 会把 <code>csv</code> 中写的值转换为十六进制，并取低 8 位作为游戏代码。</p><p>例如<code>代码,08231000181818110</code>这种情况，游戏代码为 <code>301712126</code>，处于 Eramaker 可处理的范围内。</p><p>Emuera 不会重现该行为。</p><p>在 ver 1.803 及更早版本的 Emuera 中，诸如<code>代码,08231000181818110</code>的情况，游戏代码会变为 0。</p><p>Emuera 可以处理 <code>-9223372036854775808</code> 到 <code>9223372036854775807</code> 范围内的数字，但</p><p><code>GAMEBASE_GAMECODE</code> 与 Eramaker 一样只能处理 <code>-2147483648</code> 到 <code>2147483647</code> 范围内的数字，超出该范围时会被设为 0。</p><p>此外，在 ver 1.804 之后的 Emuera 中，即使是<code>代码,08231000181818110</code>这种情况，游戏代码也会如所写的那样变为 <code>8231000181818110</code>。</p><p>（<code>GAMEBASE_GAMECODE</code> 也被修改为与其他变量处理相同的范围。）</p><p>这种情况下，如果像<code>代码,98231000181818110110</code>这样超出 Emuera 可处理的数值范围，游戏代码也会变为 0。</p><p>另外，在 ver 1.805 之后的 Emuera 中，如果存档数据的游戏代码为 0，则不论游戏本体的游戏代码如何，都可以读取。</p><h3 id="abl-csv-等的读取方法" tabindex="-1"><code>abl.csv</code> 等的读取方法 <a class="header-anchor" href="#abl-csv-等的读取方法" aria-label="Permalink to “abl.csv 等的读取方法”">​</a></h3><p>在 Eramaker 中，可以为索引指定负值或非常大的值，例如<code>99999:技巧</code>。</p><p>不过，这里指定的编号会被 <code>PRINT_ABL</code> 等使用，因此在 <code>PRINT_ABL</code> 时（在 Eramaker 内部）会引用 <code>ABL:99999</code>，从而发生错误。</p><p>因此，实际可用的值与 <code>ABL</code>、<code>TALENT</code> 的数组数量相同。</p><p>在 <code>item.csv</code> 中，当在 <code>SHOP</code> 中引用 <code>ITEM</code> 或 <code>ITEMSALES</code> 时也会发生错误。</p><p>Emuera 不允许指定 <code>ABL</code> 等数组范围之外的值。</p><p>这样的行会被忽略。</p><p>作为替代，可以通过 <code>VariableSize.csv</code> 改变数组的范围。</p><h3 id="train-csv-的读取方法" tabindex="-1"><code>train.csv</code> 的读取方法 <a class="header-anchor" href="#train-csv-的读取方法" aria-label="Permalink to “train.csv 的读取方法”">​</a></h3><p>基本上与其他 <code>csv</code> 文件相同，但情况稍有不同。</p><p>例如，在 Eramaker 中，即使定义<code>XXX,99999</code>，只要定义了 <code>@COM99999</code>，命令就能正常执行。</p><p>另一方面，如果定义负值，例如<code>YYY,-2</code>，命令会显示出来，但选择它时什么也不会发生。</p><p>Emuera 不会重现该行为。</p><p>可定义的范围到 <code>VariableSize.csv</code> 中指定的 <code>TRAINNAME</code> 的大小为止，超出则被忽略。</p><p>如果没有改变 <code>TRAINNAME</code> 的大小，则 0 到 999 有效。</p><h3 id="charaxx-csv-的读取方法" tabindex="-1"><code>CharaXX.csv</code> 的读取方法 <a class="header-anchor" href="#charaxx-csv-的读取方法" aria-label="Permalink to “CharaXX.csv 的读取方法”">​</a></h3><p>在 Eramaker 中，即使<code>编号</code>小于 0 或大于等于 1000，也能正常 <code>ADDCHARA</code>。</p><p>这在 Emuera 中也是相同的行为。</p><p>在 Eramaker 中，像<code>基础,0</code>这样需要第三个值却省略它时，会被当作 0。</p><p>另外，像<code>素质,0,100</code>这样不需要第三个值却指定了它时，会被忽略并变为 1。</p><p>Emuera 不会重现该行为。</p><p>如果写成<code>基础,0</code>，则 <code>MAXBASE:0</code> 变为 1；如果写成<code>素质,0,100</code>，则 <code>TALENT:0</code> 变为 100。</p><h3 id="文件的换行符" tabindex="-1">文件的换行符 <a class="header-anchor" href="#文件的换行符" aria-label="Permalink to “文件的换行符”">​</a></h3><p>在 Eramaker 中，换行符为 <code>CR</code> <code>LF</code> 和 <code>LF</code> 时视为换行，但只有 <code>CR</code> 时不会被视为换行，并会发生各种故障。</p><p>Emuera 不会重现该行为，只有 <code>CR</code> 时也视为换行。</p><h2 id="未修复的-bug-与不自然的行为" tabindex="-1">未修复的 Bug 与不自然的行为 <a class="header-anchor" href="#未修复的-bug-与不自然的行为" aria-label="Permalink to “未修复的 Bug 与不自然的行为”">​</a></h2><h3 id="文件读取顺序取决于文件系统" tabindex="-1">文件读取顺序取决于文件系统 <a class="header-anchor" href="#文件读取顺序取决于文件系统" aria-label="Permalink to “文件读取顺序取决于文件系统”">​</a></h3><p>在 Eramaker basic 中，有些情况下的行为取决于文件的读取顺序，例如 <code>CALL</code> 多重定义的函数时。</p><p>然而，在 Eramaker 中，文件读取顺序取决于文件系统，因此可能无法按预期工作。</p><p>这个问题在 Emuera 中同样会重现。</p><p>目前公开的许多脚本都假定文件系统为 NTFS，如果文件系统是 FAT 则无法正常工作。</p><h3 id="repeat-rend-结束时-count-会增加" tabindex="-1"><code>REPEAT</code>-<code>REND</code> 结束时 <code>COUNT</code> 会增加 <a class="header-anchor" href="#repeat-rend-结束时-count-会增加" aria-label="Permalink to “REPEAT-REND 结束时 COUNT 会增加”">​</a></h3><p>在 Eramaker 中，退出 <code>REPEAT</code>-<code>REND</code> 时 <code>COUNT</code> 会 +1。</p><p>用 <code>BREAK</code> 退出时也会 +1。</p><p>Emuera 重现了该行为。</p><p>在 <code>FOR</code>-<code>NEXT</code> 语法中，循环变量同样会 +1。</p><p>请注意，该行为与一般编程语言中的 <code>for</code> 语法和 <code>break</code> 语句不同。</p><h3 id="nextcom-的行为" tabindex="-1"><code>NEXTCOM</code> 的行为 <a class="header-anchor" href="#nextcom-的行为" aria-label="Permalink to “NEXTCOM 的行为”">​</a></h3><p>在 Eramaker 中，<code>NEXTCOM</code> 的初始值是 -1，但 <code>NEXTCOM</code> 被执行后赋予的值不是 -1 而是 0。</p><p>因此，除非在 ERB 中重新赋值，否则会不断重复 <code>COM0</code>。</p><p>另外，Eramaker 的官方说明中没有提到 <code>NEXTCOM</code> 的存在。</p><p>Emuera 也重现了该行为。</p><p><code>NEXTCOM</code> 的功能只是为了与 Eramaker 兼容而复制的，不建议使用。</p><p>如果代码不打算在 Eramaker 中运行，请考虑使用 <code>DOTRAIN</code> 或 <code>CALLTRAIN</code> 指令。</p><h2 id="变更的特性" tabindex="-1">变更的特性 <a class="header-anchor" href="#变更的特性" aria-label="Permalink to “变更的特性”">​</a></h2><h3 id="sp-角色" tabindex="-1">SP 角色 <a class="header-anchor" href="#sp-角色" aria-label="Permalink to “SP 角色”">​</a></h3><p>在 Eramaker 中，<code>csv</code> 中 <code>CFLAG:0</code> 被设置为非 0 的角色是 SP 角色。</p><p>它无法通过 <code>ADDCHARA</code> 注册，必须通过 <code>ADDSPCHARA</code> 注册，这是一个稍显晦涩的规范。</p><p>同时，它也是 bug 的来源：例如在无意中将 <code>CFLAG:0</code> 设为非 0 后，就无法再用 <code>ADDCHARA</code> 注册。</p><p>Emuera 从 ver 1.816 开始决定不再默认支持该功能。</p><p><code>CFLAG:0</code> 不再被特殊对待，所有角色都可以通过 <code>ADDCHARA</code> 注册。</p><p>兼容性选项「使用 SP 角色」可以重现 Eramaker 的行为，但除了让旧脚本运行之外，不建议将其用于任何目的。</p><h2 id="新增的功能" tabindex="-1">新增的功能 <a class="header-anchor" href="#新增的功能" aria-label="Permalink to “新增的功能”">​</a></h2><p>参见 Emuera <a href="./General.html">新增的扩展语法</a>。</p>`,174)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};